(2157899, 295784, 75713, '<td valign="top">LIke the choice to make this b&amp;w</td>', 'LIke the choice to make this b&w', '2006-02-16 22:24:44.000000', NULL, 1),
(2157906, 295800, 75713, '<td valign="top">I like how her focus is directed to the hearts - her eyes are exquisite - this shot works</td>', 'I like how her focus is directed to the hearts - her eyes are exquisite - this shot works', '2006-02-16 22:27:10.000000', NULL, 1),
(2157908, 295908, 75713, '<td valign="top">sweet pooch, good focus and he has his heart in his eyes</td>', 'sweet pooch, good focus and he has his heart in his eyes', '2006-02-16 22:28:54.000000', NULL, 1),
(2157911, 295916, 75713, '<td valign="top">tone and colors are very nice.... the shadows on the left and right are a bit distracting to me</td>', 'tone and colors are very nice.... the shadows on the left and right are a bit distracting to me', '2006-02-16 22:30:21.000000', NULL, 1),
(2157915, 295895, 75713, '<td valign="top">as an old hippie, this shot has a lot of nostalgic appeal to me - the colors are wonderful - not fond of the frame though</td>', 'as an old hippie, this shot has a lot of nostalgic appeal to me - the colors are wonderful - not fond of the frame though', '2006-02-16 22:33:01.000000', NULL, 1),
(2157921, 295906, 75713, '<td valign="top">very agile models.. a lot of planning obviously</td>', 'very agile models.. a lot of planning obviously', '2006-02-16 22:34:53.000000', NULL, 1),
(2157922, 295662, 75713, '<td valign="top">sweet - well done - the soft focus suits this shot</td>', 'sweet - well done - the soft focus suits this shot', '2006-02-16 22:36:41.000000', NULL, 1),
(2157932, 295587, 75713, '<td valign="top">I like the concept behind this photo... in my opinion this shot might have benefited from having more of a color contrast between the rose and the reddish background and the scattered petals would look better if they were less arranged with whole petals</td>', 'I like the concept behind this photo... in my opinion this shot might have benefited from having more of a color contrast between the rose and the reddish background and the scattered petals would look better if they were less arranged with whole petals', '2006-02-16 22:42:34.000000', NULL, 1),
(2157938, 295719, 75713, '<td valign="top">good lighting and the overall effect is very nice</td>', 'good lighting and the overall effect is very nice', '2006-02-16 22:43:59.000000', NULL, 1),
(2157941, 295744, 75713, '<td valign="top">very well done - great focus and beautiful colors</td>', 'very well done - great focus and beautiful colors', '2006-02-16 22:45:13.000000', NULL, 1),
(2157944, 295881, 75713, '<td valign="top">this is so well done... the hands of a hard working miner cradeling the heart is a great representation of Neil''s lyric</td>', 'this is so well done... the hands of a hard working miner cradeling the heart is a great representation of Neil''s lyric', '2006-02-16 22:48:45.000000', NULL, 1),
(2157945, 295840, 75713, '<td valign="top">a novel approach to the challenge...</td>', 'a novel approach to the challenge...', '2006-02-16 22:50:01.000000', NULL, 1),
(2157947, 295889, 75713, '<td valign="top">I really love the soft focus and the saturated colors.</td>', 'I really love the soft focus and the saturated colors.', '2006-02-16 22:52:09.000000', NULL, 1),
(2157950, 295478, 75713, '<td valign="top">something about this very strange depiction of ''heart'' really appeals to me.</td>', 'something about this very strange depiction of ''heart'' really appeals to me.', '2006-02-16 22:55:01.000000', NULL, 1),
(2157952, 295663, 75713, '<td valign="top">nicely photographed - might be more visually effective if the background was more of a contrast to the heart.</td>', 'nicely photographed - might be more visually effective if the background was more of a contrast to the heart.', '2006-02-16 22:56:45.000000', NULL, 1),
(2157957, 295473, 75713, '<td valign="top">a good creative technique</td>', 'a good creative technique', '2006-02-16 22:57:58.000000', NULL, 1),
(2157962, 295628, 75713, '<td valign="top">well done photo - his camera and his dad - yeah, that works</td>', 'well done photo - his camera and his dad - yeah, that works', '2006-02-16 23:01:48.000000', NULL, 1),
(2157968, 295551, 75713, '<td valign="top">creative idea to have the face in the heart</td>', 'creative idea to have the face in the heart', '2006-02-16 23:04:46.000000', NULL, 1),
(2157985, 295537, 75713, '<td valign="top">A very Daliesque approach to this challenge...... wonderful hues and tones - the rings around the heart reminds me of the petals of a flower</td>', 'A very Daliesque approach to this challenge...... wonderful hues and tones - the rings around the heart reminds me of the petals of a flower', '2006-02-16 23:11:33.000000', NULL, 1),
(2157995, 295562, 75713, '<td valign="top">This is a very lovely photo.. the colors in the rocks are the colors of the earth and the reflection in the water is subtle but effective.. something that I would like to see is a variation of this shot showing a dramatic raw umber/gold sky</td>', 'This is a very lovely photo.. the colors in the rocks are the colors of the earth and the reflection in the water is subtle but effective.. something that I would like to see is a variation of this shot showing a dramatic raw umber/gold sky', '2006-02-16 23:16:27.000000', NULL, 1),
(2158006, 295734, 75713, '<td valign="top">I like the idea of this shot... I would have liked the color tones inside the hands to be the same as outside</td>', 'I like the idea of this shot... I would have liked the color tones inside the hands to be the same as outside', '2006-02-16 23:20:28.000000', NULL, 1),
(2158010, 295911, 75713, '<td valign="top">nice abstract - like the color and the softness</td>', 'nice abstract - like the color and the softness', '2006-02-16 23:22:44.000000', NULL, 1),
(2158013, 295590, 75713, '<td valign="top">I really like the idea of this concept.. the heart in the book is so well done... I would like to see this same shot done in a sepia duotone</td>', 'I really like the idea of this concept.. the heart in the book is so well done... I would like to see this same shot done in a sepia duotone', '2006-02-16 23:24:15.000000', NULL, 1),
(2158047, 295919, 43437, '<td valign="top">ouch, did that hurt?  I had to laugh at this one.  Nice fit for the challenge, love how you photoshopped this together.</td>', 'ouch, did that hurt?  I had to laugh at this one.  Nice fit for the challenge, love how you photoshopped this together.', '2006-02-16 23:38:20.000000', NULL, 1),
(2158054, 295702, 75713, '<td valign="top">Well done..... her expression is bittersweet - slightly ambiguous is the presence of the heart and the cross above the modestly exposed breast, which I like</td>', 'Well done..... her expression is bittersweet - slightly ambiguous is the presence of the heart and the cross above the modestly exposed breast, which I like', '2006-02-16 23:39:47.000000', NULL, 1),
(2158057, 295816, 43437, '<td valign="top">Nice whispy feel here, like spring evenings.  Love the touch of red for the heart.</td>', 'Nice whispy feel here, like spring evenings.  Love the touch of red for the heart.', '2006-02-16 23:40:47.000000', NULL, 1),
(2158061, 295727, 43437, '<td valign="top">THis is so simple but very well done.  And I just noticed the heart in the middle.  Alot of the detail of the actual kiwi was lost but it doesnt detract much from this.  Nice lighting and you made me smile. 10</td>', 'THis is so simple but very well done.  And I just noticed the heart in the middle.  Alot of the detail of the actual kiwi was lost but it doesnt detract much from this.  Nice lighting and you made me smile. 10', '2006-02-16 23:42:31.000000', NULL, 1),
(2158063, 295792, 75713, '<td valign="top">good use of color and shadows.</td>', 'good use of color and shadows.', '2006-02-16 23:42:57.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2158065, 295811, 42005, '<td valign="top">Extremely emotional and lovely photograph and hopefully a ribbon winner. Ten.</td>', 'Extremely emotional and lovely photograph and hopefully a ribbon winner. Ten.', '2006-02-16 23:43:31.000000', NULL, 1),
(2158068, 295906, 42005, '<td valign="top">9</td>', '9', '2006-02-16 23:43:48.000000', NULL, 1),
(2158069, 295676, 75713, '<td valign="top">sweet</td>', 'sweet', '2006-02-16 23:44:12.000000', NULL, 1),
(2158072, 295875, 43437, '<td valign="top">my first impression of this was its elegance.  Almost looks like angle wings, at least the longer I look at it. I just love this, simple elegance, great lighting, incredible detail of the heart the beautiful rich red background, all make this a 10 for me.</td>', 'my first impression of this was its elegance.  Almost looks like angle wings, at least the longer I look at it. I just love this, simple elegance, great lighting, incredible detail of the heart the beautiful rich red background, all make this a 10 for me.', '2006-02-16 23:44:33.000000', NULL, 1),
(2158079, 295733, 75713, '<td valign="top">the lighting is great, the heart made out of smoke is well done.</td>', 'the lighting is great, the heart made out of smoke is well done.', '2006-02-16 23:47:26.000000', NULL, 1),
(2158084, 295601, 43437, '<td valign="top">wonderful idea here.  When I look at a picture I try to think of ways to improve it.  I cant think of a thing I would change here.  Wonderful subject, the look, the kind of sorrowful expression, pulls me in a bit.  Add in this wonderful flashy thing on the chest and the "shadow" of your past.  All makes this a great picture.  Maybe a more misty feel to the shadow but not important.</td>', 'wonderful idea here.  When I look at a picture I try to think of ways to improve it.  I cant think of a thing I would change here.  Wonderful subject, the look, the kind of sorrowful expression, pulls me in a bit.  Add in this wonderful flashy thing on the chest and the "shadow" of your past.  All makes this a great picture.  Maybe a more misty feel to the shadow but not important.', '2006-02-16 23:48:25.000000', NULL, 1),
(2158085, 295674, 75713, '<td valign="top">what a fun shot... light-hearted indeed</td>', 'what a fun shot... light-hearted indeed', '2006-02-16 23:48:35.000000', NULL, 1),
(2158089, 295719, 43437, '<td valign="top">This really is just simply beautiful.  Such a warm golden glow.  the only part i dont like are the lines on the right side, they seem out of place when everything else is so fluid.</td>', 'This really is just simply beautiful.  Such a warm golden glow.  the only part i dont like are the lines on the right side, they seem out of place when everything else is so fluid.', '2006-02-16 23:49:54.000000', NULL, 1),
(2158098, 295628, 43437, '<td valign="top">:(  makes me want to pat you on the shoulder and say its ok and something about good things coming for those who wait....  But anywho  this is a well set up shot, good lighting, nice touch with the tattoo, and I can feel your emotion which is my requirement for a 10.  So here is to a DPC addiction!</td>', ':(  makes me want to pat you on the shoulder and say its ok and something about good things coming for those who wait....  But anywho  this is a well set up shot, good lighting, nice touch with the tattoo, and I can feel your emotion which is my requirement for a 10.  So here is to a DPC addiction!', '2006-02-16 23:53:46.000000', NULL, 1),
(2158100, 295903, 25678, '<td valign="top">Well executed, different take on this challenge.  Nice lighting!</td>', 'Well executed, different take on this challenge.  Nice lighting!', '2006-02-16 23:54:41.000000', NULL, 1),
(2158102, 295883, 75713, '<td valign="top">creative - however, this shot would have worked better if the rose had been blended more subtley with her face.. the yellow in her eye and nose is distracting (washing her out) and so I would love to see this shot redone with the yellows de-emphasized</td>', 'creative - however, this shot would have worked better if the rose had been blended more subtley with her face.. the yellow in her eye and nose is distracting (washing her out) and so I would love to see this shot redone with the yellows de-emphasized', '2006-02-16 23:54:55.000000', NULL, 1),
(2158106, 295727, 25678, '<td valign="top">Very creative and well executed!</td>', 'Very creative and well executed!', '2006-02-16 23:55:36.000000', NULL, 1),
(2158109, 295885, 75713, '<td valign="top">an excellent anti-drug message..... very well done!</td>', 'an excellent anti-drug message..... very well done!', '2006-02-16 23:56:49.000000', NULL, 1),
(2158110, 295662, 43437, '<td valign="top">Very cute picture, heartwarming and romantic.  Took me a bit to notice the hearts in the eyes and made me wish I had thought of that for my entry!  I might have lost the sunglasses to let more of the hair forward but then again it adds an element of the challenge to the actual picture so its a good thing.  Anyway, well done.</td>', 'Very cute picture, heartwarming and romantic.  Took me a bit to notice the hearts in the eyes and made me wish I had thought of that for my entry!  I might have lost the sunglasses to let more of the hair forward but then again it adds an element of the challenge to the actual picture so its a good thing.  Anyway, well done.', '2006-02-16 23:56:51.000000', NULL, 1),
(2158113, 295809, 43437, '<td valign="top">Good subject and title nicely ties me to your thoughts.  You might have wanted to clone out a little of the glare on the top but its ok there.</td>', 'Good subject and title nicely ties me to your thoughts.  You might have wanted to clone out a little of the glare on the top but its ok there.', '2006-02-16 23:59:36.000000', NULL, 1),
(2158115, 295860, 75713, '<td valign="top">original idea - well executed</td>', 'original idea - well executed', '2006-02-17 00:01:26.000000', NULL, 1),
(2158117, 295769, 75713, '<td valign="top">nice study in perspective - interesting colors.</td>', 'nice study in perspective - interesting colors.', '2006-02-17 00:03:15.000000', NULL, 1),
(2158125, 295805, 75713, '<td valign="top">this made me laugh!</td>', 'this made me laugh!', '2006-02-17 00:07:20.000000', NULL, 1),
(2158126, 295781, 43437, '<td valign="top">I like this, inspired idea, good hand positions.  On the editing for some reason the red just around the outside doesnt do it for me, it looks half finished, i might have done a little more editing to take out the b/g of the house, maybe a whiteish glow from the b/g blending into, like its shining out of your hands.</td>', 'I like this, inspired idea, good hand positions.  On the editing for some reason the red just around the outside doesnt do it for me, it looks half finished, i might have done a little more editing to take out the b/g of the house, maybe a whiteish glow from the b/g blending into, like its shining out of your hands.', '2006-02-17 00:07:32.000000', NULL, 1),
(2158130, 295811, 43437, '<td valign="top">good coloring, nice texture of the map, flag blend.  For some reason I dont like how the top right corner cuts off but no biggie.</td>', 'good coloring, nice texture of the map, flag blend.  For some reason I dont like how the top right corner cuts off but no biggie.', '2006-02-17 00:09:01.000000', NULL, 1),
(2158133, 295758, 53247, '<td valign="top">AWESOME!!!!!!!</td>', 'AWESOME!!!!!!!', '2006-02-17 00:11:43.000000', NULL, 1),
(2158138, 295772, 43437, '<td valign="top">very whimsical feeling, nice pink colors, good lighting.  On the editing the only thing I notice is that to make it look like she is actually blowing it im not sure there should be any of the white behind her hand.  You really dont notice it on the first look, i came back to comment and I guess im in a disecting mood!  Anyway, well done and a great idea.</td>', 'very whimsical feeling, nice pink colors, good lighting.  On the editing the only thing I notice is that to make it look like she is actually blowing it im not sure there should be any of the white behind her hand.  You really dont notice it on the first look, i came back to comment and I guess im in a disecting mood!  Anyway, well done and a great idea.', '2006-02-17 00:13:26.000000', NULL, 1),
(2158140, 295758, 75713, '<td valign="top">this is so well done... I like the out of focus background and the crisply focused model - to me this is a very ethereal, almost biblical concept. You show the concept of love being a type of surrendering very effectively - my first 10</td>', 'this is so well done... I like the out of focus background and the crisply focused model - to me this is a very ethereal, almost biblical concept. You show the concept of love being a type of surrendering very effectively - my first 10', '2006-02-17 00:13:53.000000', NULL, 1),
(2158144, 295903, 43437, '<td valign="top">very powerful feeling, i like the grittyniss of this.  good coloring, very simple but emotional.  Im bumping this up to a 10, the more i look the more i like it.</td>', 'very powerful feeling, i like the grittyniss of this.  good coloring, very simple but emotional.  Im bumping this up to a 10, the more i look the more i like it.', '2006-02-17 00:15:44.000000', NULL, 1),
(2158145, 295557, 75713, '<td valign="top">the white roses and the red heart are a delicate balance that you have achieved well - the exposure on the white roses is excellent.</td>', 'the white roses and the red heart are a delicate balance that you have achieved well - the exposure on the white roses is excellent.', '2006-02-17 00:16:12.000000', NULL, 1),
(2158148, 295906, 43437, '<td valign="top">I not sure what anyone else will think of this but I love it!  Very artsy.  Would love to know how you set this up, they are all different people arent they?  Would like to see more of the U, it kind of leaves us hanging and almost seems lopsided since we can see the others heads.</td>', 'I not sure what anyone else will think of this but I love it!  Very artsy.  Would love to know how you set this up, they are all different people arent they?  Would like to see more of the U, it kind of leaves us hanging and almost seems lopsided since we can see the others heads.', '2006-02-17 00:18:38.000000', NULL, 1),
(2158149, 295808, 75713, '<td valign="top">I just love the big head and the little feet....... you made my night -  LMAO - you should donate this shot to your local SPCA</td>', 'I just love the big head and the little feet....... you made my night -  LMAO - you should donate this shot to your local SPCA', '2006-02-17 00:18:47.000000', NULL, 1),
(2158159, 295585, 43437, '<td valign="top">very scary look youve got going here.  I like the added touch of the wall in the heart.</td>', 'very scary look youve got going here.  I like the added touch of the wall in the heart.', '2006-02-17 00:25:37.000000', NULL, 1),
(2158166, 295444, 75713, '<td valign="top">an original creative concept.. color and focus is excellent - if I was hard pressed to come up with a constructive critisism, (very minor) it would be to center the photo more to the right.</td>', 'an original creative concept.. color and focus is excellent - if I was hard pressed to come up with a constructive critisism, (very minor) it would be to center the photo more to the right.', '2006-02-17 00:28:03.000000', NULL, 1),
(2158169, 295623, 75713, '<td valign="top">A wonderfully photographed subject - I would have liked to have seen an all red background but given the fine detail in the hairs around the chin area, that probably would have been impossible</td>', 'A wonderfully photographed subject - I would have liked to have seen an all red background but given the fine detail in the hairs around the chin area, that probably would have been impossible', '2006-02-17 00:30:54.000000', NULL, 1),
(2158192, 295465, 75713, '<td valign="top">I love the iridescent quality of the eye and the crisp focus of the shot.. I would have liked this shot better if the heart in the eye had more depth and texture.</td>', 'I love the iridescent quality of the eye and the crisp focus of the shot.. I would have liked this shot better if the heart in the eye had more depth and texture.', '2006-02-17 00:41:44.000000', NULL, 1),
(2158198, 295822, 75713, '<td valign="top">sweet child</td>', 'sweet child', '2006-02-17 00:43:13.000000', NULL, 1),
(2158203, 295470, 41337, '<td valign="top">Love the tone and composition.</td>', 'Love the tone and composition.', '2006-02-17 00:49:11.000000', NULL, 1),
(2158206, 295533, 75713, '<td valign="top">this young persons face is so beautiful - for me, the heart does not have enough detail to compliment his beauty.</td>', 'this young persons face is so beautiful - for me, the heart does not have enough detail to compliment his beauty.', '2006-02-17 00:52:23.000000', NULL, 1),
(2158207, 295583, 75713, '<td valign="top">cute</td>', 'cute', '2006-02-17 00:52:56.000000', NULL, 1),
(2158214, 295835, 75713, '<td valign="top">Interesting shot... I really like how you used a farily mundane part of the city to express your idea.....  one quibble I have is in your use of green hue, which may have been boosted too much</td>', 'Interesting shot... I really like how you used a farily mundane part of the city to express your idea.....  one quibble I have is in your use of green hue, which may have been boosted too much', '2006-02-17 01:01:51.000000', NULL, 1),
(2158216, 295760, 75713, '<td valign="top">nice reflection</td>', 'nice reflection', '2006-02-17 01:02:25.000000', NULL, 1),
(2158229, 295673, 75713, '<td valign="top">surrealistic is a term that comes to mind as I view your submission.... the flame in the votive is not there.. but it is in the reflection. I like that.. I like the kittie too - the well saturated red in the petal heart is a nice contrast to the B&amp;W of the rest of the photo</td>', 'surrealistic is a term that comes to mind as I view your submission.... the flame in the votive is not there.. but it is in the reflection. I like that.. I like the kittie too - the well saturated red in the petal heart is a nice contrast to the B&W of the rest of the photo', '2006-02-17 01:13:23.000000', NULL, 1),
(2158231, 295919, 41337, '<td valign="top">Looks like the key killed him.</td>', 'Looks like the key killed him.', '2006-02-17 01:15:12.000000', NULL, 1),
(2158232, 295910, 75713, '<td valign="top">precious</td>', 'precious', '2006-02-17 01:15:18.000000', NULL, 1),
(2158235, 295671, 41337, '<td valign="top">lol</td>', 'lol', '2006-02-17 01:17:06.000000', NULL, 1),
(2158242, 295622, 41337, '<td valign="top">First off, great idea. I like the sharpness, lighting, tones and the ring flash. However, nothing I associate "heart" with is represented here. There''s no feeling of love, warmth, passion or anything. The model has an emotionless look about her almost android-like. The photo from a technical standpoint is really good.</td>', 'First off, great idea. I like the sharpness, lighting, tones and the ring flash. However, nothing I associate "heart" with is represented here. There''s no feeling of love, warmth, passion or anything. The model has an emotionless look about her almost android-like. The photo from a technical standpoint is really good.', '2006-02-17 01:24:03.000000', NULL, 1),
(2158249, 295537, 41337, '<td valign="top">Nice abstract illustration.</td>', 'Nice abstract illustration.', '2006-02-17 01:27:43.000000', NULL, 1),
(2158513, 295562, 36981, '<td valign="top">Gorgeous.  A beautiful image.</td>', 'Gorgeous.  A beautiful image.', '2006-02-17 06:46:51.000000', NULL, 1),
(2158514, 295561, 36981, '<td valign="top">My first ten of the series, and I won''t be surprised if it''s still my favorite at the end of it.<br/> <br/>I''m back to say that I finished voting &amp; I so love this image.  Still my absolute favorite by far!  Gorgeous tones, concept , composition, etc.</td>', 'My first ten of the series, and I won''t be surprised if it''s still my favorite at the end of it. I''m back to say that I finished voting & I so love this image.  Still my absolute favorite by far!  Gorgeous tones, concept , composition, etc.', '2006-02-17 06:46:59.000000', NULL, 1),
(2158568, 295702, 53529, '<td valign="top">Grate Photo! I love the expression in the models eye and face.</td>', 'Grate Photo! I love the expression in the models eye and face.', '2006-02-17 07:32:52.000000', NULL, 1),
(2158657, 295733, 29906, '<td valign="top">This is awesome, I am not sure whether you did this through editing or not, but it''s a great shot regardless .. 10</td>', 'This is awesome, I am not sure whether you did this through editing or not, but it''s a great shot regardless .. 10', '2006-02-17 08:58:37.000000', NULL, 1),
(2158661, 295444, 29906, '<td valign="top">Great idea, very creative .. 10</td>', 'Great idea, very creative .. 10', '2006-02-17 09:00:57.000000', NULL, 1),
(2158664, 295811, 29906, '<td valign="top">Nice, 10</td>', 'Nice, 10', '2006-02-17 09:02:00.000000', NULL, 1),
(2158667, 295887, 29906, '<td valign="top">Daniel Cuesta of course, good shot ..</td>', 'Daniel Cuesta of course, good shot ..', '2006-02-17 09:08:53.000000', NULL, 1),
(2158719, 295719, 36499, '<td valign="top">my guess...dax? i love the colors of this and a wonderful "action shot" hope to see this at the top! wonderful...just wonderful 10</td>', 'my guess...dax? i love the colors of this and a wonderful "action shot" hope to see this at the top! wonderful...just wonderful 10', '2006-02-17 09:57:39.000000', NULL, 1),
(2158726, 295542, 33515, '<td valign="top">Very simple and clean, nice photo</td>', 'Very simple and clean, nice photo', '2006-02-17 10:04:40.000000', NULL, 1),
(2158730, 295662, 33515, '<td valign="top">I like the photo and concept, but the sunglasses on your subjects head bug me. I had to keep looking in that area of the photo trying to figure out what they were. Nice photo anyway.</td>', 'I like the photo and concept, but the sunglasses on your subjects head bug me. I had to keep looking in that area of the photo trying to figure out what they were. Nice photo anyway.', '2006-02-17 10:06:59.000000', NULL, 1),
