(2168486, 295911, 42132, '<td valign="top">honestly can''t say what exactly it is that appeals to me about this image. the thumbnail really caught my eye,colours,light/shade,the muted colours through the shadow...ok I give up.8</td>', 'honestly can''t say what exactly it is that appeals to me about this image. the thumbnail really caught my eye,colours,light/shade,the muted colours through the shadow...ok I give up.8', '2006-02-21 16:05:01.000000', NULL, 1),
(2168505, 295473, 18219, '<td valign="top">very abstract and trippy!!!<br/>nice choice of colors and well composed.</td>', 'very abstract and trippy!!!nice choice of colors and well composed.', '2006-02-21 16:16:42.000000', NULL, 1),
