(2168525, 295808, 50631, '<td valign="top">This is the cutest face ever! Great expression! I wish I could take him home.</td>', 'This is the cutest face ever! Great expression! I wish I could take him home.', '2006-02-21 16:35:21.000000', NULL, 1),
(2168558, 295734, 22734, '<td valign="top">The treatment here leans more on a graphical representation but the effect is rather nice and the coloration has an old time feel. Happy that you took this direction because the majority of images did not take advantage of the loose rules. 8</td>', 'The treatment here leans more on a graphical representation but the effect is rather nice and the coloration has an old time feel. Happy that you took this direction because the majority of images did not take advantage of the loose rules. 8', '2006-02-21 16:59:56.000000', NULL, 1),
